import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.jit
def _square_partial_sum_kernel(
    x_ptr,
    partial_ptr,
    n_elements,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < n_elements
    x = tl.load(x_ptr + offs, mask=mask, other=0.0)
    partial = tl.sum(x * x, axis=0)
    tl.store(partial_ptr + pid, partial)


def _square_mean_launcher(x):
    x = x.contiguous()
    n_elements = x.numel()

    if n_elements == 0:
        return torch.mean(x)

    block = 4096
    n_blocks = triton.cdiv(n_elements, block)

    if x.dtype in (torch.float16, torch.bfloat16):
        partial_dtype = torch.float32
    else:
        partial_dtype = x.dtype

    partials = torch.empty(
        (n_blocks,),
        device=x.device,
        dtype=partial_dtype,
    )

    _square_partial_sum_kernel[(n_blocks,)](
        x,
        partials,
        n_elements,
        BLOCK=block,
        num_warps=8,
    )

    result = torch.sum(partials) / n_elements
    return result.to(dtype=x.dtype)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, predictions, targets):
        difference = predictions - targets
        return _square_mean_launcher(difference)
